reference_solution:
def groupAnagrams(strs):
    groups = {}
    for s in strs:
        groups.setdefault("".join(sorted(s)), []).append(s)
    return list(groups.values())

brute_force_solution:
def groupAnagrams(strs):
    groups = []
    for s in strs:
        for g in groups:
            if sorted(g[0]) == sorted(s):
                g.append(s)
                break
        else:
            groups.append([s])
    return groups

